FILE Client.dfy
include "OrderFacts.dfy"
include "Reachability.dfy"
module Client {
  import O = OrderFacts
  import R = Reachability
  lemma Connect(a: int, b: int, c: int)
    requires O.Before(a, b) && O.Before(b, c)
    ensures R.Reach(a, c)
  {
  }
}

FILE OrderFacts.dfy
module OrderFacts {
  export provides Before, Transitive
  opaque predicate Before(a: int, b: int) { a <= b }

  lemma Transitive(a: int, b: int, c: int)
    requires Before(a, b) && Before(b, c)
    ensures Before(a, c)
  { reveal Before(); }
}

FILE Reachability.dfy
include "OrderFacts.dfy"
module Reachability {
  import O = OrderFacts
  export provides O, Reach, Lift
  opaque predicate Reach(a: int, b: int) { O.Before(a, b) }

  lemma Lift(a: int, b: int)
    requires O.Before(a, b)
    ensures Reach(a, b)
  { reveal Reach(); }
}

